document.addEventListener("DOMContentLoaded", () => {
import("./crew-member.js").then((module) => {
    const deneb = new module.default({ name: "Deneb", role: "Cook" });
    console.log("test: Deneb's call sign is " + deneb.callSign);
    deneb.name = "Altair";
    console.log("test: renamed, it is " + deneb.callSign);
    const kept = Object.getOwnPropertyDescriptor(module.default.prototype, "callSign");
    console.log("test: callSign is " + (kept && kept.get ? "a getter" : "something else"));
  })
  .catch((error) => console.log("test: failed " + error.message));
});
